@extends('layouts.app') @section('title','Comments') @section('content')<section class="page"><h1>Comments</h1>@include('dashboard._nav')<table class="table"><tr><th>Reader</th><th>Comment</th><th>Status</th></tr>@foreach($comments as $comment)<tr><td>{{ $comment->user_name }}<br><small>{{ $comment->user_email }}</small></td><td>{{ Str::limit($comment->comment,120) }}</td><td><form class="inline" method="post" action="{{ route('dashboard.comments.update',$comment) }}">@csrf @method('patch')<select name="status"><option @selected($comment->status==='pending')>pending</option><option @selected($comment->status==='approved')>approved</option><option @selected($comment->status==='rejected')>rejected</option></select><button>Save</button></form></td></tr>@endforeach</table>{{ $comments->links() }}</section>@endsection
